/**
 * Solar Panel Power-Up: the power board, and turning the tiles.
 *
 * The board is generated by `sim/trainingSolar.ts`; this file draws it and
 * turns the tiles the player taps. The power that reaches the battery is
 * drawn in the sun's colour, so the player can see how far the line goes.
 */

import { h } from '../dom/h';
import { icon } from './icons';
import { playSfx } from './sfx';
import {
  SOLAR_SIZE,
  generateSolarPuzzle,
  rotateSolarTile,
  solarDifficulty,
  solarFlow,
  solarOpens,
  solarPerformance,
  type SolarTile,
} from '../sim/trainingSolar';
import type { TrainingGameMount } from './trainingGame';

/** The four sides of a tile, in the order they are drawn. */
const SIDES = ['up', 'right', 'down', 'left'] as const;

/**
 * The board.
 *
 * Four by four of power tiles. The solar panel is on the left of the top
 * tile and the battery is on the right of the bottom one; the player has to
 * join them with one unbroken line.
 */
export const mountSolar: TrainingGameMount = (root, context) => {
  /* How hard this round is: fewer spare turns over the answer. */
  const difficulty = solarDifficulty(context.level);

  const puzzle = generateSolarPuzzle(context.random);
  const limit = puzzle.needed + difficulty.spare;

  let tiles: readonly (readonly SolarTile[])[] = puzzle.tiles;
  let used = 0;
  let finished = false;
  let over = false;

  const board = h('div', { class: 'trn__solar' });
  const hint = h('p', { class: 'trn__hint', text: 'Turn the tiles. Join the panel to the battery.' });

  root.append(board, hint);

  function tileNode(tile: SolarTile, lit: boolean): HTMLElement {
    const node = h('button', { class: `trn__wire${lit ? ' trn__wire--lit' : ''}`, type: 'button', 'aria-label': 'Turn this tile', 'data-sfx-hover': 'off' });
    const open = solarOpens(tile);

    SIDES.forEach((side, index) => {
      const arm = h('span', { class: `trn__arm trn__arm--${side}` });

      if (!open.includes(index)) arm.classList.add('trn__arm--closed');

      node.append(arm);
    });

    node.append(h('span', { class: 'trn__wire-core' }));

    return node;
  }

  function paint(): void {
    const { lit } = solarFlow(tiles);
    const cells: HTMLElement[] = [];

    for (let row = 0; row < SOLAR_SIZE; row += 1) {
      const panel = h('span', { class: 'trn__solar-end' }, row === 0 ? icon('sun', 'The solar panel') : null);

      cells.push(panel);

      for (let column = 0; column < SOLAR_SIZE; column += 1) {
        const tile = tiles[row]?.[column];

        if (tile === undefined) continue;

        const node = tileNode(tile, lit.has(`${row},${column}`));

        node.addEventListener('click', () => turn(row, column));
        cells.push(node);
      }

      cells.push(h('span', { class: 'trn__solar-end' }, row === SOLAR_SIZE - 1 ? icon('bolt', 'The battery') : null));
    }

    board.replaceChildren(...cells);
    context.setStatus(`Turns left: ${limit - used}`);
  }

  function turn(row: number, column: number): void {
    if (finished || over) return;

    playSfx('wire-turn');
    tiles = rotateSolarTile(tiles, row, column);
    used += 1;
    paint();

    if (solarFlow(tiles).win) {
      finished = true;
      hint.textContent = 'The battery is charging!';

      window.setTimeout(() => context.onComplete(solarPerformance(used, puzzle.needed, difficulty)), 600);

      return;
    }

    /* Out of turns is not a punishment: the round still counts as a finished
       game, and the player is paid for the attempt. */
    if (used >= limit) {
      finished = true;
      hint.textContent = 'Out of turns.';

      window.setTimeout(() => context.onComplete(solarPerformance(used, puzzle.needed, difficulty)), 600);
    }
  }

  paint();

  return {
    destroy(): void {
      root.replaceChildren();
    },
  };
};
